  pub(crate) modules: Table<'src, Self>,
  #[serde(skip)]
  pub(crate) name: Option<Name<'src>>,
  #[serde(skip)]
  pub(crate) private: bool,
  pub(crate) recipes: Table<'src, Arc<Recipe<'src>>>,
  pub(crate) settings: Settings,
