  #[test]
  fn from_str() {
    #[track_caller]
    fn case(s: &str, takes_shell_name: bool, extension: &str) {
      let kind = ShellKind::from(s);
      assert_eq!(
        kind.takes_shell_name(),
        takes_shell_name,
        "takes_shell_name for {s:?}"
      );
      assert_eq!(kind.extension(), extension, "extension for {s:?}");
